package org.pocketlore.app;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
public final class SpecialistInstrumentation extends Instrumentation {
 JSONObject report=new JSONObject();JSONArray checks=new JSONArray(),queries=new JSONArray(),inspections=new JSONArray();String mode,runId;File dir;Activity activity;
 void ok(boolean b,String s){if(!b)throw new AssertionError(s);checks.put(s);}
 byte[] bytes(File f)throws Exception{return Files.readAllBytes(f.toPath());}
 public void onCreate(Bundle b){super.onCreate(b);mode=b.getString("mode","install");runId=b.getString("run_id","unbound");start();}
 public void onStart(){Bundle result=new Bundle();try{
  report.put("run_id",runId);File files=getTargetContext().getFilesDir();dir=new File(files,"specialist-tests");PackLibrary lib=new PackLibrary(files);File archive=new File(dir,"valid.plpack");String hash=KnowledgePack.hash(bytes(archive));PackLibrary.Snapshot before=lib.load();Set<String> active=new HashSet<>();for(PackLibrary.Entry e:before.entries)if(e.active)active.add(e.hash);
  long begin=SystemClock.elapsedRealtime();PackLibrary.Snapshot installed;
  if(mode.equals("install")){try(InputStream in=new FileInputStream(archive)){installed=lib.install(in,()->false);}}else installed=lib.load();
  report.put("import_or_reload_ms",SystemClock.elapsedRealtime()-begin).put("pack_sha256",hash);ok(installed.entries.stream().anyMatch(e->e.hash.equals(hash)&&e.active),"Pinned edition installed and active "+mode);ok(installed.distinctDocuments>=before.distinctDocuments,"Prior document collection retained");
  byte[] catalog=bytes(new File(files,"pack-library/catalog.json"));JSONArray rejects=new JSONArray();
  if(mode.equals("install")){
   for(String name:new String[]{"corrupt","rights","span"}){boolean rejected=false;String error="";try(InputStream in=new FileInputStream(new File(dir,name+".plpack"))){lib.install(in,()->false);}catch(Exception e){rejected=true;error=e.toString();}ok(rejected&&Arrays.equals(catalog,bytes(new File(files,"pack-library/catalog.json"))),"Reject and rollback "+name);rejects.put(new JSONObject().put("case",name).put("error",error));}
   for(boolean immediate:new boolean[]{true,false}){final int[] reads={0};boolean rejected=false;long start=SystemClock.elapsedRealtime();try(InputStream in=new FilterInputStream(new FileInputStream(archive)){public int read(byte[] b,int o,int n)throws IOException{reads[0]++;return super.read(b,o,Math.min(n,128));}}){lib.install(in,()->immediate||reads[0]>1);}catch(InterruptedIOException e){rejected=true;}ok(rejected&&Arrays.equals(catalog,bytes(new File(files,"pack-library/catalog.json"))),"Cancellation rollback "+immediate);rejects.put(new JSONObject().put("cancel_before",immediate).put("ms",SystemClock.elapsedRealtime()-start));}
   active.add(hash);Set<String> disabled=new HashSet<>(active);disabled.remove(hash);PackLibrary.Snapshot off=lib.select(disabled);for(ResearchEngine.Hit h:off.engine.research("typed structured data hashing signing").hits)ok(!h.passage.id.startsWith("p"+hash+"_"),"Disabled specialist source excluded");installed=lib.select(active);
   ByteArrayOutputStream out=new ByteArrayOutputStream();lib.exportCollection(hash,out,()->false);ok(Arrays.equals(out.toByteArray(),bytes(archive)),"Portable export preserves exact archive");
   ok(new File(files,"pack-library").listFiles((d,n)->n.endsWith(".partial")).length==0,"No import stages remain");
  }
  report.put("rejections",rejects);report.put("run_id",runId);JSONObject protocol=new JSONObject(new String(bytes(new File(dir,"protocol.json")),StandardCharsets.UTF_8));
  activity=startActivitySync(new Intent(getTargetContext(),ScaleActivity.class).putExtra("section","Library").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
  for(int i=0;i<protocol.getJSONArray("queries").length();i++){
   JSONObject c=protocol.getJSONArray("queries").getJSONObject(i);String q=c.getString("query");long start=SystemClock.elapsedRealtime();ResearchEngine.Result r=installed.engine.research(q);JSONArray hits=new JSONArray();ResearchEngine.Hit selected=null;
   for(ResearchEngine.Hit h:r.hits){hits.put(new JSONObject().put("id",h.passage.id).put("text",h.passage.text));if(h.passage.id.startsWith("p"+hash+"_"+c.getString("document")+"-"))selected=h;}
   queries.put(new JSONObject().put("query",q).put("ms",SystemClock.elapsedRealtime()-start).put("hits",hits));ok(selected!=null,"Frozen query retrieves document "+c.getString("document"));
   ResearchEngine.Hit h=selected;String detail=MainActivity.sourceDetail(h);ok(detail.contains("Original Markdown UTF-16 range:")&&detail.contains("CC0 1.0 Universal")&&detail.contains("status Final")&&detail.contains(hash),"Rendered source dates rights span and edition "+i);
   if(mode.equals("install")){long readerStart=SystemClock.elapsedRealtime();ActivityMonitor monitor=addMonitor(SourceReaderActivity.class.getName(),null,false);runOnMainSync(()->ReaderUi.openSource(activity,h.passage.title,detail,"Retrieved historical specification; no generated answer."));Activity reader=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);ok(reader instanceof SourceReaderActivity,"Actual source reader opened "+i);SourceReaderActivity sr=(SourceReaderActivity)reader;long end=SystemClock.elapsedRealtime()+10000;while(sr.entry==null&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);ok(sr.entry!=null&&sr.entry.body.equals(detail),"Actual source body preserves complete renderer "+i);ok(sr.entry.portable().contains(h.passage.text),"Saved export preserves formula/code text "+i);inspections.put(new JSONObject().put("id",h.passage.id).put("reader_ms",SystemClock.elapsedRealtime()-readerStart).put("body",sr.entry.body));runOnMainSync(reader::finish);waitForIdleSync();}
  }
  for(int i=0;i<protocol.getJSONArray("absent").length();i++){String q=protocol.getJSONArray("absent").getString(i);ok(installed.engine.research(q).hits.isEmpty(),"Invented absent token returns no evidence");}
  android.os.Debug.MemoryInfo memory=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(memory);report.put("pss_kib",memory.getTotalPss()).put("app_data_bytes",SharedShardUpdate.uniqueBytes(new File(getTargetContext().getApplicationInfo().dataDir))).put("archive_bytes",archive.length()).put("collections",installed.entries.size()).put("documents",installed.distinctDocuments).put("passages",installed.engine.size()).put("status","PASS");
 }catch(Throwable e){try{report.put("status","FAIL").put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}
 finally{if(activity!=null)runOnMainSync(activity::finish);try{report.put("checks",checks).put("queries",queries).put("inspections",inspections);Files.write(new File(dir,mode+".json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));result.putString("report",report.toString());}catch(Exception e){result.putString("error",e.toString());}finish(report.optString("status").equals("PASS")?-1:1,result);}}
}
